def compute(vars):
    apac = vars["v1"]
    amer = vars["v2"]
    difference = apac - amer
    return {
        "value": difference,
        "trace": {
            "apac_operating_income": apac,
            "amer_operating_income": amer,
            "difference": difference,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
